const menu=document.querySelector('.menu-btn'),nav=document.querySelector('.navigation');
function closeMenu(){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false');if(menu)menu.textContent='Menu'}
menu?.addEventListener('click',()=>{const open=!nav.classList.contains('open');nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close':'Menu'});
nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){closeMenu();menu.focus()}});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){document.documentElement.classList.add('motion');const io=new IntersectionObserver(items=>items.forEach(x=>{if(x.isIntersecting){x.target.classList.add('shown');io.unobserve(x.target)}}),{threshold:.05});document.querySelectorAll('.reveal').forEach(x=>io.observe(x))}
const scenes=[...document.querySelectorAll('.scene')],selectors=[...document.querySelectorAll('[data-scene]')];let sceneIndex=0;
function changeScene(i){sceneIndex=(i+scenes.length)%scenes.length;scenes.forEach((s,j)=>{s.classList.toggle('active',j===sceneIndex);s.setAttribute('aria-hidden',String(j!==sceneIndex));s.tabIndex=j===sceneIndex?0:-1});selectors.forEach((b,j)=>b.setAttribute('aria-pressed',String(j===sceneIndex)));const s=scenes[sceneIndex];document.querySelector('#scene-name').textContent=s.dataset.name;document.querySelector('#scene-client').textContent=s.dataset.client;document.querySelector('#scene-counter').textContent=`${String(sceneIndex+1).padStart(2,'0')} / ${String(scenes.length).padStart(2,'0')}`}
selectors.forEach(b=>b.addEventListener('click',()=>changeScene(Number(b.dataset.scene))));document.querySelector('#scene-next')?.addEventListener('click',()=>changeScene(sceneIndex+1));document.querySelector('#scene-prev')?.addEventListener('click',()=>changeScene(sceneIndex-1));document.querySelector('.screening')?.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();changeScene(sceneIndex+1)}if(e.key==='ArrowLeft'){e.preventDefault();changeScene(sceneIndex-1)}});
const destinations=['dumb-biryani','district-films','only-fridays','first-time-with-simba','plus91','in-dyou-time','hold-my-popcorn','the-sports-women','journeys-of-aspiration'];document.querySelectorAll('[data-surprise]').forEach(b=>b.addEventListener('click',()=>{location.href='/work/'+destinations[Math.floor(Math.random()*destinations.length)]+'/'}));
const filters=[...document.querySelectorAll('[data-filter]')],cards=[...document.querySelectorAll('.portfolio-wall .project-card')];function filterProjects(value,update=true){if(!filters.some(b=>b.dataset.filter===value))value='All';filters.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===value)));let count=0;cards.forEach(c=>{c.hidden=value!=='All'&&c.dataset.category!==value;if(!c.hidden)count++});const status=document.querySelector('.work-count');if(status)status.textContent=`${count} ${count===1?'project':'projects'}${value==='All'?'':` / ${value}`}`;if(update){const u=new URL(location);value==='All'?u.searchParams.delete('category'):u.searchParams.set('category',value);history.replaceState(null,'',u)}}filters.forEach(b=>b.addEventListener('click',()=>filterProjects(b.dataset.filter)));if(filters.length)filterProjects(new URL(location).searchParams.get('category')||'All',false);
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.portfolio-wall').classList.toggle('index-mode',b.dataset.view==='index');document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));
const form=document.querySelector('#brief-form');form?.addEventListener('submit',ev=>{ev.preventDefault();if(!form.reportValidity())return;const d=new FormData(form),name=String(d.get('name')).trim(),company=String(d.get('company')).trim(),service=String(d.get('service'));const body=`Hi Revolio,\n\nI'm ${name}${company?` from ${company}`:''}.\n\nI'm interested in: ${service}\n\n${String(d.get('brief')).trim()}\n\nReply to: ${String(d.get('email')).trim()}\n\nThanks,\n${name}`;const link=document.querySelector('#email-draft');link.href=`mailto:info@revolio.in?subject=${encodeURIComponent(`Project enquiry: ${service}`)}&body=${encodeURIComponent(body)}`;document.querySelector('#form-result').hidden=false;link.focus()});

if(matchMedia("(hover:hover) and (prefers-reduced-motion:no-preference)").matches){const frame=document.querySelector(".screening");frame?.addEventListener("pointermove",ev=>{const r=frame.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width-.5,y=(ev.clientY-r.top)/r.height-.5;frame.style.transform=`perspective(1200px) rotate(${2+x}deg) rotateY(${x*3}deg) rotateX(${-y*3}deg)`});frame?.addEventListener("pointerleave",()=>{frame.style.transform=""})}
